  "I confirm this batch was prepared under hygienic conditions, is safe for immediate consumption, and has been kept properly covered.": "ಈ ಬ್ಯಾಚ್ ಅನ್ನು ನೈರ್ಮಲ್ಯದ ಪರಿಸ್ಥಿತಿಗಳಲ್ಲಿ ತಯಾರಿಸಲಾಗಿದೆ, ತಕ್ಷಣದ ಬಳಕೆಗೆ ಸುರಕ್ಷಿತವಾಗಿದೆ ಮತ್ತು ಸರಿಯಾಗಿ ಮುಚ್ಚಿಡಲಾಗಿದೆ ಎಂದು ನಾನು ಖಚಿತಪಡಿಸುತ್ತೇನೆ.",
  "I confirm this buffet surplus was maintained under food hygiene standards, packed in clean insulated food-grade containers, and is ready for safe community redistribution.": "ಈ ಬಫೆಟ್ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಆಹಾರ ನೈರ್ಮಲ್ಯ ಮಾನದಂಡಗಳ ಅಡಿಯಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗಿದೆ, ಶುದ್ಧ ಇನ್ಸುಲೇಟೆಡ್ ಫುಡ್-ಗ್ರೇಡ್ ಪಾತ್ರೆಗಳಲ್ಲಿ ಪ್ಯಾಕ್ ಮಾಡಲಾಗಿದೆ ಮತ್ತು ಸುರಕ್ಷಿತ ಸಮುದಾಯ ಮರುಹಂಚಿಕೆಗೆ ಸಿದ್ಧವಾಗಿದೆ ಎಂದು ನಾನು ಖಚಿತಪಡಿಸುತ್ತೇನೆ.",
  "🍗 15kg Chicken Curry & Rotis": "🍗 15 ಕಿ.ಗ್ರಾಂ ಚಿಕನ್ ಕರಿ ಮತ್ತು ರೊಟ್ಟಿಗಳು",
  "🍛 15 Chapatis & Sabzi (~5 people)": "🍛 15 ಚಪಾತಿಗಳು ಮತ್ತು ಪಲ್ಯ (~5 ಜನರು)",
  "🍛 18kg Dal Makhani & Rice": "🍛 18 ಕಿ.ಗ್ರಾಂ ದಾಲ್ ಮಖನಿ ಮತ್ತು ಅನ್ನ",
  "🍛 35kg Wedding Banquet Buffet": "🍛 35 ಕಿ.ಗ್ರಾಂ ಮದುವೆ ಔತಣಕೂಟ ಬಫೆಟ್",
  "🍲 12kg Veg Biryani & Raita": "🍲 12 ಕಿ.ಗ್ರಾಂ ವೆಜ್ ಬಿರಿಯಾನಿ ಮತ್ತು ರಾಯತ",
  "🍲 2.5 kg Veg Pulao & Dal (~6 people)": "🍲 2.5 ಕಿ.ಗ್ರಾಂ ವೆಜ್ ಪುಲಾವ್ ಮತ್ತು ಬೇಳೆ ಸಾರು (~6 ಜನರು)",
  "🎉 5 kg Family Gathering Surplus (~14 people)": "🎉 5 ಕಿ.ಗ್ರಾಂ ಕೌಟುಂಬಿಕ ಸಮಾರಂಭದ ಹೆಚ್ಚುವರಿ ಆಹಾರ (~14 ಜನರು)",
  "🥐 15kg Bakery & Bread Cartons": "🥐 15 ಕಿ.ಗ್ರಾಂ ಬೇಕರಿ ಮತ್ತು ಬ್ರೆಡ್ ಬಾಕ್ಸ್‌ಗಳು",
  "🥞 20kg Breakfast Buffet (Idli/Vada)": "🥞 20 ಕಿ.ಗ್ರಾಂ ಉಪಾಹಾರ ಬಫೆಟ್ (ಇಡ್ಲಿ/ವಡೆ)",
  "Delivering donor surplus to communities.": "ಸಮುದಾಯಗಳಿಗೆ ದಾನಿಗಳ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ವಿತರಿಸುವುದು.",
  "Reducing kitchen waste.": "ಅಡುಗೆಮನೆಯ ತ್ಯಾಜ್ಯವನ್ನು ಕಡಿಮೆ ಮಾಡುವುದು.",
  "Sharing extra food with local people in need.": "ಸ್ಥಳೀಯ ಅಗತ್ಯವಿರುವ ಜನರೊಂದಿಗೆ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಹಂಚಿಕೊಳ್ಳುವುದು.",
  "Zero buffet food to landfill.": "ಬಫೆಟ್ ಆಹಾರವನ್ನು ಕಸದ ಗುಂಡಿಗೆ ಎಸೆಯುವುದನ್ನು ತಡೆಯುವುದು.",
  "Hot held in food-grade insulated thermal containers (>65°C). Handover from kitchen back entrance.": "ಆಹಾರ ದರ್ಜೆಯ ಶಾಖ-ನಿರೋಧಕ ಕಂಟೈನರ್‌ಗಳಲ್ಲಿ ಬಿಸಿಯಾಗಿ ಇರಿಸಲಾಗಿದೆ (>65°C). ಅಡುಗೆಮನೆಯ ಹಿಂಬದಿಯ ಪ್ರವೇಶ ದ್ವಾರದಿಂದ ಹಸ್ತಾಂತರ.",
  "Report to Service Gate / Loading Bay 2. Security will guide driver to service elevator with pre-packed thermal containers.": "ಸರ್ವೀಸ್ ಗೇಟ್ / ಲೋಡಿಂಗ್ ಬೇ 2 ಗೆ ವರದಿ ಮಾಡಿ. ಮೊದಲೇ ಪ್ಯಾಕ್ ಮಾಡಲಾದ ಥರ್ಮಲ್ ಕಂಟೈನರ್‌ಗಳೊಂದಿಗೆ ಚಾಲಕನನ್ನು ಸರ್ವೀಸ್ ಲಿಫ್ಟ್‌ಗೆ ಸೆಕ್ಯುರಿಟಿ ಮಾರ್ಗದರ್ಶನ ಮಾಡುತ್ತಾರೆ.",
  "Freshly Cooked / Food Safe": "ತಾಜಾ ಬೇಯಿಸಿದ / ಆಹಾರ ಸುರಕ್ಷಿತ",
  "Freshly cooked, hot held >65°C, untouched.": "ತಾಜಾ ಬೇಯಿಸಿದ, >65°C ನಲ್ಲಿ ಬಿಸಿಯಾಗಿ ಇರಿಸಲಾದ, ಮುಟ್ಟದ ಆಹಾರ.",
  "Pristine buffet surplus, packed in insulated thermal containers.": "ಉತ್ತಮ ಬಫೆಟ್ ಹೆಚ್ಚುವರಿ ಆಹಾರ, ಶಾಖ-ನಿರೋಧಕ ಕಂಟೈನರ್‌ಗಳಲ್ಲಿ ಪ್ಯಾಕ್ ಮಾಡಲಾಗಿದೆ.",
  "Safely fed to community": "ಸಮುದಾಯಕ್ಕೆ ಸುರಕ್ಷಿತವಾಗಿ ಉಣಬಡಿಸಲಾಗಿದೆ",
  "Meals served at shelters": "ಆಶ್ರಯ ತಾಣಗಳಲ್ಲಿ ಊಟ ನೀಡಲಾಗಿದೆ",
  "Fast Demo 1-Click Pre-fill:": "ತ್ವರಿತ ಡೆಮೊ 1-ಕ್ಲಿಕ್ ಸ್ವಯಂ-ಭರ್ತಿ:",
  "Quick Donate 1-Click Samples:": "ತ್ವರಿತ ದಾನ 1-ಕ್ಲಿಕ್ ಮಾದರಿಗಳು:",
  "Packaging & Handover Instructions": "ಪ್ಯಾಕೇಜಿಂಗ್ ಮತ್ತು ಹಸ್ತಾಂತರ ಸೂಚನೆಗಳು",
  "Residential Address (For Handover)": "ವಸತಿ ವಿಳಾಸ (ಹಸ್ತಾಂತರಕ್ಕಾಗಿ)",
  "Registered Headquarters Address": "ನೋಂದಾಯಿತ ಪ್ರಧಾನ ಕಛೇರಿಯ ವಿಳಾಸ",
  "Registration / DARPAN ID": "ನೋಂದಣಿ / ದರ್ಪಣ್ ಐಡಿ",
  "Reason for Surplus (Optional Context)": "ಹೆಚ್ಚುವರಿ ಆಹಾರದ ಕಾರಣ (ಐಚ್ಛಿಕ ಮಾಹಿತಿ)",
  "Profile updated successfully!": "ಪ್ರೊಫೈಲ್ ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ!",
  "Hotel Food Donations": "ಹೋಟೆಲ್ ಆಹಾರ ದಾನಗಳು",
  "Hotel Portal": "ಹೋಟೆಲ್ ಪೋರ್ಟಲ್",
  "Hotel Profile & Logistics Info": "ಹೋಟೆಲ್ ಪ್ರೊಫೈಲ್ ಮತ್ತು ಲಾಜಿಸ್ಟಿಕ್ಸ್ ಮಾಹಿತಿ",
  "Hotel Surplus Posting": "ಹೋಟೆಲ್ ಹೆಚ್ಚುವರಿ ಆಹಾರ ಪೋಸ್ಟಿಂಗ್",
