  "Meal Type / Category *": "ಊಟದ ಪ್ರಕಾರ / ವರ್ಗ *",
  "Notes for Volunteer (Optional)": "ಸ್ವಯಂಸೇವಕರಿಗೆ ಟಿಪ್ಪಣಿಗಳು (ಐಚ್ಛಿಕ)",
  "Loading donation form...": "ದಾನ ನಮೂನೆ ಲೋಡ್ ಆಗುತ್ತಿದೆ...",
  "Loading hotel donation form...": "ಹೋಟೆಲ್ ದಾನ ನಮೂನೆ ಲೋಡ್ ಆಗುತ್ತಿದೆ...",
  "No active pickups in progress.": "ಪ್ರಗತಿಯಲ್ಲಿ ಯಾವುದೇ ಸಕ್ರಿಯ ಪಿಕಪ್‌ಗಳಿಲ್ಲ.",
  "No completed food deliveries recorded yet.": "ಇನ್ನೂ ಯಾವುದೇ ಪೂರ್ಣಗೊಂಡ ಆಹಾರ ವಿತರಣೆಗಳು ದಾಖಲಾಗಿಲ್ಲ.",
  "No food donations available nearby right now.": "ಪ್ರಸ್ತುತ ಹತ್ತಿರದಲ್ಲಿ ಯಾವುದೇ ಆಹಾರ ದಾನಗಳು ಲಭ್ಯವಿಲ್ಲ.",
  "Once you accept donations and complete OTP handovers with donors, your delivery receipts will be logged here.": "ನೀವು ದಾನಗಳನ್ನು ಸ್ವೀಕರಿಸಿ ದಾನಿಗಳೊಂದಿಗೆ OTP ಹಸ್ತಾಂತರವನ್ನು ಪೂರ್ಣಗೊಳಿಸಿದ ನಂತರ, ನಿಮ್ಮ ವಿತರಣಾ ರಶೀದಿಗಳು ಇಲ್ಲಿ ದಾಖಲಾಗುತ್ತವೆ.",
  "Once you claim a food listing from a restaurant, hotel, or household, volunteer coordination and handover OTPs will appear here.": "ನೀವು ರೆಸ್ಟೋರೆಂಟ್, ಹೋಟೆಲ್ ಅಥವಾ ಮನೆಯಿಂದ ಆಹಾರ ಪಟ್ಟಿಯನ್ನು ಸ್ವೀಕರಿಸಿದ ನಂತರ, ಸ್ವಯಂಸೇವಕರ ಸಮನ್ವಯ ಮತ್ತು ಹಸ್ತಾಂತರ OTP ಗಳು ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "Manage your verified NGO details, contact numbers, and service coverage area.": "ನಿಮ್ಮ ಪರಿಶೀಲಿಸಿದ ಎನ್‌ಜಿಒ ವಿವರಗಳು, ಸಂಪರ್ಕ ಸಂಖ್ಯೆಗಳು ಮತ್ತು ಸೇವಾ ವ್ಯಾಪ್ತಿಯ ಪ್ರದೇಶವನ್ನು ನಿರ್ವಹಿಸಿ.",
  "NGO registration credentials are cross-verified with official government portals before live food claims are enabled.": "ಲೈವ್ ಆಹಾರ ಕ್ಲೈಮ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸುವ ಮೊದಲು ಎನ್‌ಜಿಒ ನೋಂದಣಿ ವಿವರಗಳನ್ನು ಅಧಿಕೃತ ಸರ್ಕಾರಿ ಪೋರ್ಟಲ್‌ಗಳೊಂದಿಗೆ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ.",
  "New Food Donation": "ಹೊಸ ಆಹಾರ ದಾನ",
  "Donate Buffet &amp; Banquet Surplus": "ಬಫೆಟ್ ಮತ್ತು ಔತಣಕೂಟದ ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ದಾನ ಮಾಡಿ",
  "Community Project • SDG 2 &amp; SDG 12 Alignment": "ಸಮುದಾಯ ಯೋಜನೆ • SDG 2 ಮತ್ತು SDG 12 ಹೊಂದಾಣಿಕೆ",
  "Hotel name, gate number, and full address": "ಹೋಟೆಲ್ ಹೆಸರು, ಗೇಟ್ ಸಂಖ್ಯೆ ಮತ್ತು ಪೂರ್ಣ ವಿಳಾಸ",
  "Kitchen street address and landmark": "ಅಡುಗೆಮನೆಯ ವಿಳಾಸ ಮತ್ತು ಪ್ರಮುಖ ಗುರುತು",
  "Search donations...": "ದಾನಗಳನ್ನು ಹುಡುಕಿ...",
  "Search hotel donations...": "ಹೋಟೆಲ್ ದಾನಗಳನ್ನು ಹುಡುಕಿ...",
  "e.g. Banquet Dinner Buffet: Dal Makhani, Paneer, Mixed Veg & 150 Rotis": "ಉದಾ. ಡಿನ್ನರ್ ಬಫೆಟ್: ದಾಲ್ ಮಖನಿ, ಪನೀರ್, ಮಿಕ್ಸ್‌ಡ್ ವೆಜ್ ಮತ್ತು 150 ರೊಟ್ಟಿಗಳು",
  "e.g. Dinner Ended (10:15 PM)": "ಉದಾ. ರಾತ್ರಿ ಊಟ ಮುಕ್ತಾಯ (ರಾತ್ರಿ 10:15)",
  "e.g. Hot held in sealed stainless steel containers. Enter via kitchen back door.": "ಉದಾ. ಸೀಲ್ ಮಾಡಿದ ಸ್ಟೀಲ್ ಕಂಟೈನರ್‌ಗಳಲ್ಲಿ ಬಿಸಿಯಾಗಿ ಇರಿಸಲಾಗಿದೆ. ಅಡುಗೆಮನೆಯ ಹಿಂಬಾಗಿಲಿನಿಂದ ಪ್ರವೇಶಿಸಿ.",
  "e.g. Lunch Service (1:30 PM)": "ಉದಾ. ಮಧ್ಯಾಹ್ನದ ಊಟ ಸೇವೆ (ಮಧ್ಯಾಹ್ನ 1:30)",
  "e.g. Today, 8:30 PM": "ಉದಾ. ಇಂದು, ರಾತ್ರಿ 8:30",
  "e.g. Tonight, 11:30 PM": "ಉದಾ. ಇಂದು ರಾತ್ರಿ, 11:30",
  "e.g. Vegetable Dum Biryani, Mixed Veg & 50 Rotis": "ಉದಾ. ವೆಜಿಟೇಬಲ್ ದಮ್ ಬಿರಿಯಾನಿ, ಮಿಕ್ಸ್‌ಡ್ ವೆಜ್ ಮತ್ತು 50 ರೊಟ್ಟಿಗಳು",
  "e.g. Vehicle entry via Gate 3 loading dock. Contact banquet shift supervisor.": "ಉದಾ. ಗೇಟ್ 3 ಲೋಡಿಂಗ್ ಡಾಕ್ ಮೂಲಕ ವಾಹನ ಪ್ರವೇಶ. ಔತಣಕೂಟದ ಶಿಫ್ಟ್ ಮೇಲ್ವಿಚಾರಕರನ್ನು ಸಂಪರ್ಕಿಸಿ.",
  "Requested": "ವಿನಂತಿಸಲಾಗಿದೆ",
  "Accepted": "ಸ್ವೀಕರಿಸಲಾಗಿದೆ",
  "Pending": "ಬಾಕಿ ಉಳಿದಿದೆ",
  "Ready for Pickup": "ಪಿಕಪ್‌ಗೆ ಸಿದ್ಧವಾಗಿದೆ",
  "Cancelled": "ರದ್ದುಗೊಳಿಸಲಾಗಿದೆ",
  "No active food listings. Post surplus food to connect with local hunger relief organizations.": "ಯಾವುದೇ ಸಕ್ರಿಯ ಆಹಾರ ಪಟ್ಟಿಗಳಿಲ್ಲ. ಸ್ಥಳೀಯ ಹಸಿವು ಪರಿಹಾರ ಸಂಸ್ಥೆಗಳೊಂದಿಗೆ ಸಂಪರ್ಕ ಸಾಧಿಸಲು ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಪೋಸ್ಟ್ ಮಾಡಿ.",
