  "No past pickups on record yet.": "ದಾಖಲೆಯಲ್ಲಿ ಇನ್ನೂ ಯಾವುದೇ ಹಿಂದಿನ ಪಿಕಪ್‌ಗಳಿಲ್ಲ.",
  "Newly posted donations will appear here in real-time as donors list surplus food.": "ದಾನಿಗಳು ಹೆಚ್ಚುವರಿ ಆಹಾರವನ್ನು ಪಟ್ಟಿ ಮಾಡಿದಂತೆ ಹೊಸದಾಗಿ ಪೋಸ್ಟ್ ಮಾಡಲಾದ ದಾನಗಳು ಇಲ್ಲಿ ನೈಜ ಸಮಯದಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
