  "Get instant alerts for surplus food, spoilage warnings, and pickup updates — even when this tab is closed.": "ಪಡೆಯಿರಿ ತ್ವರಿತ ಎಚ್ಚರಿಕೆಗಳು ಗಾಗಿ ಹೆಚ್ಚುವರಿ ಆಹಾರ ಆಹಾರ, ಹಾಳಾಗುವಿಕೆ ಎಚ್ಚರಿಕೆಗಳು, ಮತ್ತು ಪಿಕಪ್ ನವೀಕರಣಗಳು — ಸಹ ಯಾವಾಗ ಈ ಟ್ಯಾಬ್ ಆಗಿದೆ ಮುಚ್ಚಲಾಗಿದೆ.",
