  "You can enable them in your browser's site settings.": "ನೀವು ಮಾಡಬಹುದು ಸಕ್ರಿಯಗೊಳಿಸಿ ಅವುಗಳನ್ನು ನಲ್ಲಿ ನಿಮ್ಮ ಬ್ರೌಸರ್'s ತಾಣ ಸೆಟ್ಟಿಂಗ್‌ಗಳು.",
  "Navigation": "ನ್ಯಾವಿಗೇಷನ್",
  "Connected": "ಸಂಪರ್ಕಗೊಂಡಿದೆ",
  "Connect": "ಸಂಪರ್ಕಿಸಿ",
  "Linked": "ಲಿಂಕ್ ಮಾಡಲಾಗಿದೆ",
  "Receive urgent notifications when surplus is claimed or route dispatched": "ಸ್ವೀಕರಿಸಿ ತುರ್ತು ಅಧಿಸೂಚನೆಗಳು ಯಾವಾಗ ಹೆಚ್ಚುವರಿ ಆಹಾರ ಆಗಿದೆ ಸ್ವೀಕರಿಸಲಾಗಿದೆ ಅಥವಾ ಮಾರ್ಗ ರವಾನಿಸಲಾಗಿದೆ",
  "Play gentle notification sound on live NGO claims & IoT anomalies": "ಪ್ಲೇ ಮಾಡಿ ಸೌಮ್ಯ ಅಧಿಸೂಚನೆ ಧ್ವನಿ ಮೇಲೆ ಲೈವ್ NGO ಕ್ಲೈಮ್‌ಗಳು & IoT ವೈಪರೀತ್ಯಗಳು",
  "Auto-deliver forecasted meal requirements every morning at 06:00 AM": "ಸ್ವಯಂ-ವಿತರಿಸಿ ಮುನ್ಸೂಚಿತ ಊಟ ಅಗತ್ಯತೆಗಳು ಪ್ರತಿ ಬೆಳಿಗ್ಗೆ ನಲ್ಲಿ 06:00 ಬೆಳಿಗ್ಗೆ",
  "Surplus exceeding this amount automatically triggers matching priority to nearest certified NGOs.": "ಹೆಚ್ಚುವರಿ ಆಹಾರ ಮೀರುತ್ತಿರುವ ಈ ಮೊತ್ತ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪ್ರಚೋದಕಗಳು ಹೊಂದಾಣಿಕೆ ಆದ್ಯತೆ ಗೆ ಹತ್ತಿರದ ಪ್ರಮಾಣೀಕರಿಸಲಾಗಿದೆ NGOs.",
  "Alerts with model confidence above this score require warden or plant manager confirmation.": "ಎಚ್ಚರಿಕೆಗಳು ಜೊತೆಗೆ ಮಾದರಿ ವಿಶ್ವಾಸಾರ್ಹತೆ ಮೇಲೆ ಈ ಅಂಕ ಅಗತ್ಯವಿದೆ ವಾರ್ಡನ್ ಅಥವಾ ಸ್ಥಾವರ ವ್ಯವಸ್ಥಾಪಕ ದೃಢೀಕರಣ.",
  "Your institutional facility is verified under the National Food Recovery Network. All surplus donations receive immutable digital chain-of-custody hashes.": "ನಿಮ್ಮ ಸಾಂಸ್ಥಿಕ ಸೌಲಭ್ಯ ಆಗಿದೆ ದೃಢೀಕರಿಸಲಾಗಿದೆ ಅಡಿಯಲ್ಲಿ ದಿ ರಾಷ್ಟ್ರೀಯ ಆಹಾರ ಚೇತರಿಕೆ ನೆಟ್‌ವರ್ಕ್. ಎಲ್ಲಾ ಹೆಚ್ಚುವರಿ ಆಹಾರ ದಾನಗಳು ಸ್ವೀಕರಿಸಿ ಬದಲಾಯಿಸಲಾಗದ ಡಿಜಿಟಲ್ ಸರಪಳಿ-ನ-ಪಾಲನೆ / ಹೊಣೆ ಹ್ಯಾಶ್‌ಗಳು.",
  "Settings apply across all modules": "ಸೆಟ್ಟಿಂಗ್‌ಗಳು ಅನ್ವಯಿಸಿ ಉದ್ದಕ್ಕೂ ಎಲ್ಲಾ ಮಾಡ್ಯೂಲ್‌ಗಳು",
  "Prioritizes zero food shortages by buffering portions slightly (+5%).": "ಆದ್ಯತೆ ನೀಡುತ್ತದೆ ಶೂನ್ಯ ಆಹಾರ ಕೊರತೆಗಳು ಮೂಲಕ ಬಫರಿಂಗ್ ಭಾಗಗಳು ಸ್ವಲ್ಪ ಮಟ್ಟಿಗೆ (+5%).",
  "Optimal trade-off minimizing both food waste and stockouts (Recommended).": "ಸೂಕ್ತ / ಇಷ್ಟತಮ ವ್ಯಾಪಾರ-ಆಫ್ ಕನಿಷ್ಠಗೊಳಿಸುವುದು ಎರಡೂ ಆಹಾರ ತ್ಯಾಜ್ಯ ಮತ್ತು ದಾಸ್ತಾನು ಕೊರತೆಗಳು (Recommended).",
  "Strict zero-waste optimization targeting exact attendance figures.": "ಕಟ್ಟುನಿಟ್ಟಾದ ಶೂನ್ಯ-ತ್ಯಾಜ್ಯ ಆಪ್ಟಿಮೈಸೇಶನ್ ಗುರಿಯಾಗಿಸಿಕೊಂಡು ನಿಖರ ಹಾಜರಾತಿ ಅಂಕಿಅಂಶಗಳು.",
