  "Your complaint has been assigned to the FoodWise Rapid Response Quality Desk. If food is inedible, our auto-matching engine is locating immediate backup surplus for your shelter.": "ನಿಮ್ಮ complaint ಹೊಂದಿದೆ ಆಗಿದೆ ನಿಯೋಜಿಸಲಾಗಿದೆ ಗೆ ದಿ FoodWise ತ್ವರಿತ ಪ್ರತಿಕ್ರಿಯೆ ಗುಣಮಟ್ಟ ಡೆಸ್ಕ್. ಒಂದು ವೇಳೆ ಆಹಾರ ಆಗಿದೆ ತಿನ್ನಲಾಗದ, ನಮ್ಮ ಸ್ವಯಂ-ಹೊಂದಾಣಿಕೆ ಎಂಜಿನ್ ಆಗಿದೆ ಪತ್ತೆಹಚ್ಚಲಾಗುತ್ತಿದೆ ತಕ್ಷಣದ ಬ್ಯಾಕಪ್ ಹೆಚ್ಚುವರಿ ಆಹಾರ ಗಾಗಿ ನಿಮ್ಮ ಆಶ್ರಯ ತಾಣ.",
  "FoodWise Admin Ticket:": "FoodWise ನಿರ್ವಾಹಕ ಟಿಕೆಟ್:",
