  "What issue are you facing with this donation?": "ಏನು ಸಮಸ್ಯೆ ಇವೆ ನೀವು ಎದುರಿಸುತ್ತಿರುವ ಜೊತೆಗೆ ಈ ದಾನ?",
  "Select the incident category to trigger the appropriate FoodWise Admin resolution workflow": "ಆಯ್ಕೆಮಾಡಿ ದಿ ಘಟನೆ ವರ್ಗ ಗೆ ಪ್ರಚೋದಕ ದಿ ಸೂಕ್ತ FoodWise ನಿರ್ವಾಹಕ ರೆಸಲ್ಯೂಶನ್ / ನಿರ್ಣಯ ಕಾರ್ಯಹರಿವು",
