  "NGO Volunteer Callback Number": "NGO ಸ್ವಯಂಸೇವಕ ಕಾಲ್‌ಬ್ಯಾಕ್ ಸಂಖ್ಯೆ",
  "+91 XXXXX XXXXX (For Admin to call immediately)": "+91 xxxxx xxxxx (ಗಾಗಿ ನಿರ್ವಾಹಕ ಗೆ ಕರೆ ತಕ್ಷಣವೇ)",
  "Describe the Incident *": "ವಿವರಿಸಿ ದಿ ಘಟನೆ *",
  "State clearly what happened. e.g. 'Food smelled sour when opened at the shelter', or 'Driver arrived 2 hours late and food was cold', or 'Claimed 50 kg but only 20 kg received'...": "ರಾಜ್ಯ / ಸ್ಥಿತಿ ಸ್ಪಷ್ಟವಾಗಿ ಏನು ಸಂಭವಿಸಿದೆ. e.g. 'ಆಹಾರ ವಾಸನೆ ಬಂದಿದೆ ಹುಳಿ ಯಾವಾಗ ತೆರೆಯಲಾಗಿದೆ ನಲ್ಲಿ ದಿ ಆಶ್ರಯ ತಾಣ', ಅಥವಾ 'ಚಾಲಕ ಬಂದಿದೆ 2 ಗಂಟೆಗಳು ತಡವಾಗಿ ಮತ್ತು ಆಹಾರ ಆಗಿತ್ತು ಶೀತಲ', ಅಥವಾ 'ಸ್ವೀಕರಿಸಲಾಗಿದೆ 50 kg ಆದರೆ ಮಾತ್ರ 20 kg ಸ್ವೀಕರಿಸಲಾಗಿದೆ'...",
  "characters • Be specific to help FoodWise Admin resolve quickly": "ಅಕ್ಷರಗಳು • ಆಗಿರಬೇಕು ನಿರ್ದಿಷ್ಟ ಗೆ ಸಹಾಯ FoodWise ನಿರ್ವಾಹಕ ಪರಿಹರಿಸಿ ಬೇಗನೆ",
  "Severity & Urgency": "ತೀವ್ರತೆ & ತುರ್ತು",
  "Upload Photo Evidence": "ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಫೋಟೋ ಪುರಾವೆ",
  "Take a quick photo of the packaging, temperature probe, or spoiled food for instant admin verification": "ತೆಗೆದುಕೊಳ್ಳಿ a ತ್ವರಿತ ಫೋಟೋ ನ ದಿ ಪ್ಯಾಕೇಜಿಂಗ್, ತಾಪಮಾನ ಪ್ರೋಬ್, ಅಥವಾ ಹಾಳಾದ ಆಹಾರ ಗಾಗಿ ತ್ವರಿತ ನಿರ್ವಾಹಕ ಪರಿಶೀಲನೆ",
  "Photo Evidence Attached": "ಫೋಟೋ ಪುರಾವೆ ಲಗತ್ತಿಸಲಾಗಿದೆ",
  "Take Photo with Camera": "ತೆಗೆದುಕೊಳ್ಳಿ ಫೋಟೋ ಜೊತೆಗೆ ಕ್ಯಾಮೆರಾ",
