  "Upload from Gallery / Files": "ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಇಂದ ಗ್ಯಾಲರಿ / ಫೈಲ್‌ಗಳು",
  "FoodWise Admin Resolution Guarantee": "FoodWise ನಿರ್ವಾಹಕ ರೆಸಲ್ಯೂಶನ್ / ನಿರ್ಣಯ ಖಾತರಿ",
  "< 30 Min Response:": "< 30 ಕನಿಷ್ಠ ಪ್ರತಿಕ್ರಿಯೆ:",
