  "Emergency Replacement:": "ತುರ್ತು ಬದಲಿ:",
  "If food is rejected, backup surplus is auto-dispatched from nearest mess.": "ಒಂದು ವೇಳೆ ಆಹಾರ ಆಗಿದೆ ತಿರಸ್ಕರಿಸಲಾಗಿದೆ, ಬ್ಯಾಕಪ್ ಹೆಚ್ಚುವರಿ ಆಹಾರ ಆಗಿದೆ ಸ್ವಯಂ-ರವಾನಿಸಲಾಗಿದೆ ಇಂದ ಹತ್ತಿರದ ಮೆಸ್.",
  "Donor Penalty:": "ದಾನಿ ದಂಡ:",
