  "AI Operational Recommendation:": "AI ಕಾರ್ಯಾಚರಣೆಯ ಶಿಫಾರಸು:",
  "Prioritize this batch in Production Line 2 (Puree) immediately.": "ಆದ್ಯತೆ ನೀಡಿ ಈ ಬ್ಯಾಚ್ ನಲ್ಲಿ ಉತ್ಪಾದನೆ ಲೈನ್ 2 (ಪ್ಯೂರಿ) ತಕ್ಷಣವೇ.",
  "2,800 kg (88%) is fully salvageable": "2,800 kg (88%) ಆಗಿದೆ ಸಂಪೂರ್ಣವಾಗಿ ಉಳಿಸಬಹುದಾದ",
  "for Grade-A puree if processed within the next 18 hours. After hour 24, quality drops to Grade-B (sub-standard).": "ಗಾಗಿ ದರ್ಜೆ-A ಪ್ಯೂರಿ ಒಂದು ವೇಳೆ ಸಂಸ್ಕರಿಸಿದ ಒಳಗೆ ದಿ ಮುಂದೆ 18 ಗಂಟೆಗಳು. ನಂತರ ಗಂಟೆ 24, ಗುಣಮಟ್ಟ ಹನಿಗಳು ಗೆ ದರ್ಜೆ-B (ಉಪ-ಪ್ರಮಾಣಿತ).",
