  "Total batch procurement value: ₹1,28,000. If processed now (salvage 88%): ₹1,12,640 recovered. If delayed > 31h (total spoilage): ₹1,28,000 direct loss + ₹14,000 disposal cost.": "ಒಟ್ಟು ಬ್ಯಾಚ್ ಖರೀದಿ / ಸಂಗ್ರಹಣೆ ಮೌಲ್ಯ: ₹1,28,000. ಒಂದು ವೇಳೆ ಸಂಸ್ಕರಿಸಿದ ಈಗ (ರಕ್ಷಣೆ 88%): ₹1,12,640 ಚೇತರಿಸಿಕೊಂಡ. ಒಂದು ವೇಳೆ ವಿಳಂಬವಾಗಿದೆ > 31h (ಒಟ್ಟು ಹಾಳಾಗುವಿಕೆ): ₹1,28,000 ನೇರ ನಷ್ಟ + ₹14,000 ವಿಲೇವಾರಿ ವೆಚ್ಚ.",
  "Net benefit of AI early warning: ₹1,26,640 saved.": "ನಿವ್ವಳ ಪ್ರಯೋಜನ ನ AI ಬೇಗ ಎಚ್ಚರಿಕೆ: ₹1,26,640 ಉಳಿಸಲಾಗಿದೆ.",
