// Pre-sorted list of English phrases (longest first)
export const SORTED_EN_TO_KANNADA = Object.entries(KN_PHRASE_DICTIONARY).sort(
  (a, b) => b[0].length - a[0].length
);

export function isKannada(text: string): boolean {
  return /[\u0C80-\u0CFF]/.test(text);
}

/**
 * Intelligent translator:
 * Translates English text to Kannada with strict whole-phrase matching.
 * Never performs partial word splitting on sentences to prevent mixed-language output.
 */
export function translateDynamicEnglishToKannada(text: string): string {
  if (!text || typeof text !== "string") return text;
  const trimmed = text.trim();
  if (!trimmed) return text;

  // 1. Exact phrase match
  if (KN_PHRASE_DICTIONARY[trimmed]) {
    return text.replace(trimmed, KN_PHRASE_DICTIONARY[trimmed]);
  }

  // 2. Trailing punctuation stripped match
  const stripped = trimmed.replace(/^[\s•–—\-\.:]+|[\s•–—\-\.:]+$/g, "");
  if (stripped && KN_PHRASE_DICTIONARY[stripped]) {
    return text.replace(stripped, KN_PHRASE_DICTIONARY[stripped]);
  }

  // 3. For short text or single tokens/badges (<= 3 words), check sorted phrases
  const wordCount = trimmed.split(/\s+/).length;
  if (wordCount <= 3) {
    for (const [enKey, knVal] of SORTED_EN_TO_KANNADA) {
      if (enKey.toLowerCase() === trimmed.toLowerCase()) {
        return text.replace(trimmed, knVal);
      }
    }
  }

  return text;
}

export const KANNADA_TO_ENGLISH: Record<string, string> = {};
for (const [en, kn] of Object.entries(KN_PHRASE_DICTIONARY)) {
  if (kn && typeof kn === "string" && kn.trim()) {
    KANNADA_TO_ENGLISH[kn.trim()] = en;
  }
}

export const SORTED_KANNADA_TO_ENGLISH = Object.entries(KANNADA_TO_ENGLISH).sort(
  (a, b) => b[0].length - a[0].length
);

export function translateKannadaToEnglish(text: string): string {
  if (!text || typeof text !== "string") return text;
  const trimmed = text.trim();
  if (!trimmed) return text;

  if (KANNADA_TO_ENGLISH[trimmed]) {
    return text.replace(trimmed, KANNADA_TO_ENGLISH[trimmed]);
  }

  const stripped = trimmed.replace(/^[\s•–—\-\.:]+|[\s•–—\-\.:]+$/g, "");
  if (stripped && KANNADA_TO_ENGLISH[stripped]) {
    return text.replace(stripped, KANNADA_TO_ENGLISH[stripped]);
  }

  return text;
}
